query DT($id: String!, $index: Int!, $size: Int!) {
  disease(efoId: $id) {
    id name
    associatedTargets(page: {index: $index, size: $size}) {
      count
      rows {
        score
        datatypeScores { id score }
        target { id approvedSymbol approvedName biotype }
      }
    }
  }
}
